    catch(error){({target,trigger}=liveAnswerElements(kind,data,candidates,target,trigger,originProjectId));if(target?.isConnected&&trigger){target.replaceChildren(node('p','notice',error.message));trigger.textContent='Retry personalisation';trigger.disabled=false;}}
