    $('focused-view').addEventListener('click',()=>setMode('focused'));$('directory-view').addEventListener('click',()=>setMode('directory'));$('load-more').addEventListener('click',loadMore);$('view-updated').addEventListener('click',()=>{$('view-updated').hidden=true;conversation().positions={};resume();$('results-region').scrollTop=0;});
    $('documented-only').addEventListener('change',e=>{conversation().documentedOnly=e.target.checked;refreshSearch();});$('uncontacted-only').addEventListener('change',e=>{conversation().uncontactedOnly=e.target.checked;refreshSearch();});
    $('toggle-brief').addEventListener('click',openBrief);$('brief-close').addEventListener('click',()=>closeBrief());$('brief-done').addEventListener('click',()=>closeBrief());$('brief-dialog').addEventListener('close',()=>{$('brief-slot').append($('brief-content'));$('toggle-brief').setAttribute('aria-expanded','false');if(briefReturnFocus&&state.nav.view==='results')$('toggle-brief').focus({preventScroll:true});});
    $('recovery-close').addEventListener('click',()=>$('recovery-dialog').close());$('recovery-form').addEventListener('submit',event=>{event.preventDefault();const failed=project()?.failedSearch,message=$('recovery-input').value.trim();if(!message||recoveryEdit?.projectId!==state.projectId||recoveryEdit?.id!==failed?.id)return;$('recovery-dialog').close();retryFailed(message);});
    $('compare-clear').addEventListener('click',()=>{conversation().selected.clear();syncCompare();});$('compare-open').addEventListener('click',()=>showComparison(currentData(),[...conversation().selected]));$('compare-close').addEventListener('click',()=>{if(history.state?.compareIds)history.back();else $('compare-dialog').close();});$('comparison-explain').addEventListener('click',()=>{const c=state.comparison;if(c)personalise('comparison',c.data,c.candidates,$('comparison-answer'),$('comparison-explain'));});
    $('profile-close').addEventListener('click',closeProfile);for(const id of ['profile-dialog','compare-dialog'])$(id).addEventListener('close',()=>{if($(id).dataset.silentClose){delete $(id).dataset.silentClose;return;}if(dialogClosing)return;if(state.nav.profileId||state.nav.compareIds)history.back();restoreFocus();});
    $('project-select').addEventListener('change',e=>switchProject(e.target.value));$('new-project').addEventListener('click',()=>{$('new-project-name').value='';$('new-project-dialog').showModal();});$('new-project-close').addEventListener('click',()=>$('new-project-dialog').close());$('new-project-form').addEventListener('submit',async e=>{e.preventDefault();flushDraft();const p=P.createProject($('new-project-name').value);state.projectId=p.id;try{localStorage.setItem('docmap-expert-project-id',p.id);}catch{}await persist(p);$('new-project-dialog').close();route({view:'home',searchId:null,profileId:null,compareIds:null},{skipCapture:true});refreshProjectControls();});
    $('export-json').addEventListener('click',()=>exportProject());$('copy-json').addEventListener('click',copyProjectBackup);$('export-html').addEventListener('click',()=>exportProject(true));$('emergency-export').addEventListener('click',()=>exportProject());$('import-project').addEventListener('click',()=>{$('import-error').textContent='';$('import-dialog').showModal();});$('import-close').addEventListener('click',()=>$('import-dialog').close());$('import-choose-file').addEventListener('click',()=>$('import-file').click());$('import-backup-form').addEventListener('submit',async e=>{e.preventDefault();try{await importProjectBackup($('import-text').value);}catch(error){$('import-error').textContent=error.message;}});$('import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>12_000_000)throw new Error('Choose a project export no larger than 12 MB.');await importProjectBackup(await file.text());}catch(error){toast(error.message);}finally{e.target.value='';}});
    $('project-notes').addEventListener('input',()=>state.projectEdits.set(state.projectId+'|notes',$('project-notes').value));
    $('save-project-notes').addEventListener('click',async()=>{const id=state.projectId,value=$('project-notes').value,ok=await mutateProject(id,p=>{p.notes=value;return p;});if(ok&&state.projectEdits.get(id+'|notes')===value)state.projectEdits.delete(id+'|notes');if(state.projectId===id)$('project-save-status').textContent=ok?(state.projectEdits.has(id+'|notes')?'Submitted notes saved. Your newer edits are not saved yet.':'Project notes saved.'):'Not saved to storage. Export your project now.';});
    $('event-close').addEventListener('click',()=>{eventOrigin=null;$('event-dialog').close();});$('event-dialog').addEventListener('close',()=>{if(!$('event-dialog').open)eventOrigin=null;});$('event-form').addEventListener('submit',async e=>{e.preventDefault();const origin=eventOrigin;if(!origin||origin.projectId!==state.projectId||!$('event-dialog').open||origin.pending)return;const type=$('event-type').value,detail=$('event-detail').value;origin.pending=true;try{const ok=await mutateProject(origin.projectId,p=>P.recordEvent(p,origin.candidateId,type,detail,{actor:'user'}));if(eventOrigin===origin&&state.projectId===origin.projectId){eventOrigin=null;$('event-dialog').close();renderProject();toast(ok?'Activity recorded from your input. No messages were sent.':'Activity held in memory. Export your project now.');}}catch(error){if(eventOrigin===origin&&state.projectId===origin.projectId){origin.pending=false;toast(error.message);}}});
